Object.assign(D.en, { apAbT: '“Unknown app blocked”? (Samsung Auto Blocker)', apAb1: 'Open Settings → Security and privacy → Auto Blocker and turn it off.', apAb2: 'Open the downloaded INTPROTO-TV.apk again (Downloads / My Files) and tap Install. If asked, allow “Install unknown apps” for your browser (Chrome, Opera…).', apAb3: 'After installing you can turn Auto Blocker back on: the app keeps working.', apPwaT: 'No APK? Install from Chrome instead', apPwa: 'Open intproto-tv.store/app in Chrome → menu ⋮ → Install app (or Add to Home screen). No security setting to change.', apPwaBtn: '📲 Install from Chrome' });
Object.assign(D.fr, { apAbT: '« Application inconnue bloquée » ? (Bloqueur automatique Samsung)', apAb1: 'Ouvrez Paramètres → Sécurité et confidentialité → Bloqueur automatique et désactivez-le.', apAb2: 'Rouvrez INTPROTO-TV.apk téléchargé (Téléchargements / Mes fichiers) et touchez Installer. Si demandé, autorisez « Installer des applis inconnues » pour votre navigateur (Chrome, Opera…).', apAb3: 'Après l’installation, vous pouvez réactiver le Bloqueur automatique : l’app continue de fonctionner.', apPwaT: 'Pas d’APK ? Installez depuis Chrome', apPwa: 'Ouvrez intproto-tv.store/app dans Chrome → menu ⋮ → Installer l’application (ou Ajouter à l’écran d’accueil). Aucun réglage de sécurité à changer.', apPwaBtn: '📲 Installer depuis Chrome' });
Object.assign(D.de, { apAbT: '„Unbekannte App blockiert“? (Samsung Auto Blocker)', apAb1: 'Einstellungen → Sicherheit und Datenschutz → Auto Blocker öffnen und ausschalten.', apAb2: 'Die geladene INTPROTO-TV.apk erneut öffnen (Downloads / Eigene Dateien) und Installieren tippen. Falls gefragt, „Unbekannte Apps installieren“ für Ihren Browser erlauben.', apAb3: 'Nach der Installation können Sie Auto Blocker wieder einschalten: Die App funktioniert weiter.', apPwaT: 'Kein APK? Über Chrome installieren', apPwa: 'intproto-tv.store/app in Chrome öffnen → Menü ⋮ → App installieren (oder Zum Startbildschirm). Keine Sicherheitseinstellung nötig.', apPwaBtn: '📲 Über Chrome installieren' });
Object.assign(D.es, { apAbT: '¿«App desconocida bloqueada»? (Bloqueador automático de Samsung)', apAb1: 'Abre Ajustes → Seguridad y privacidad → Bloqueador automático y desactívalo.', apAb2: 'Vuelve a abrir INTPROTO-TV.apk descargado (Descargas / Mis archivos) y toca Instalar. Si te lo pide, permite «Instalar apps desconocidas» para tu navegador.', apAb3: 'Tras instalar puedes volver a activar el Bloqueador automático: la app sigue funcionando.', apPwaT: '¿Sin APK? Instala desde Chrome', apPwa: 'Abre intproto-tv.store/app en Chrome → menú ⋮ → Instalar app (o Añadir a pantalla de inicio). Sin cambiar ajustes de seguridad.', apPwaBtn: '📲 Instalar desde Chrome' });
Object.assign(D.it, { apAbT: '«App sconosciuta bloccata»? (Blocco automatico Samsung)', apAb1: 'Apri Impostazioni → Sicurezza e privacy → Blocco automatico e disattivalo.', apAb2: 'Riapri INTPROTO-TV.apk scaricato (Download / Archivio) e tocca Installa. Se richiesto, consenti «Installa app sconosciute» per il browser.', apAb3: 'Dopo l’installazione puoi riattivare il Blocco automatico: l’app continua a funzionare.', apPwaT: 'Niente APK? Installa da Chrome', apPwa: 'Apri intproto-tv.store/app in Chrome → menu ⋮ → Installa app (o Aggiungi a schermata Home). Nessuna impostazione di sicurezza da cambiare.', apPwaBtn: '📲 Installa da Chrome' });
